require __DIR__.'/app/bootstrap.php';$u=require_login();$id=(int)($_GET['order']??$_POST['order']??0);$o=store_order($id);if(!$o||(int)$o['buyer_user_id']!==(int)$u['id']){http_response_code(404);exit('Order not found.');}if(!$o['payment_order_id']){header('Location: /order.php?id='.$id);exit;}$payment=get_payment_order((int)$o['payment_order_id']);$gateways=get_payment_gateways(true);$msg=$err=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$gateway=(string)($_POST['gateway']??'');$allowed=array_column($gateways,'code');if(!in_array($gateway,$allowed,true))throw new RuntimeException('Choose an enabled payment method.');$proof=upload_payment_proof($_FILES['proof']??[]);$ref=trim((string)($_POST['reference']??''));if($ref==='')throw new RuntimeException('Payment/reference number is required.');submit_manual_payment((int)$o['payment_order_id'],$gateway,$ref,$proof?:'');db()->prepare("UPDATE store_orders SET payment_status='awaiting_review' WHERE id=?")->execute([$id]);$msg='Payment proof submitted for review.';$payment=get_payment_order((int)$o['payment_order_id']);}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Advance Payment — ShahkotPK</title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"></head><body class="lc-page"><section class="shop-section"><div class="lt-shell" style="max-width:800px"><div class="shop-panel"><h2>Advance Payment</h2><p>Order <b><?=e($o['order_number'])?></b> · Rs <?=e(number_format((float)$o['grand_total'],0))?></p><?php if($msg):?><div style="padding:10px;background:#dcfce7;color:#166534;border-radius:9px"><?=e($msg)?></div><?php endif;?><?php if($err):?><div style="padding:10px;background:#fee2e2;color:#991b1b;border-radius:9px"><?=e($err)?></div><?php endif;?><?php if($payment['status']==='paid'):?><p>Payment approved. <a href="/order.php?id=<?=e($id)?>">Open order</a>.</p><?php else:?><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order" value="<?=e($id)?>"><label>Payment Method</label><select name="gateway" required><?php foreach($gateways as $g):?><option value="<?=e($g['code'])?>"><?=e($g['name'])?></option><?php endforeach;?></select><label>Transaction / Reference Number</label><input name="reference" required><label>Payment Proof</label><input type="file" name="proof" accept="image/*,.pdf"><button class="cv-primary-btn" style="border:0;margin-top:12px">Submit Payment for Review</button></form><?php endif;?></div></div></section></body></html>
